{"policy":"permit (
    principal is User,
    action == Action::"dispatchShipment",
    resource is Shipment
)
when {
    principal.roles.contains(Role::"Driver") ||
    principal.roles.contains(Role::"DispatchManager")
};

forbid (
    principal is User,
    action == Action::"dispatchShipment",
    resource is Shipment
)
when {
    principal == resource.planner &&
    principal == resource.driverOfRecord
}
unless {
    (context.fromDepotNetwork &&
     context has requestDepot &&
     context.requestDepot == resource.originDepot) ||
    context.trackingCodeCarriesAssignedCarrierPrefix
};

permit (
    principal is User,
    action == Action::"confirmDelivery",
    resource is DeliveryReceipt
)
when {
    principal.roles.contains(Role::"Driver") ||
    principal.roles.contains(Role::"DepotSupervisor")
};

forbid (
    principal is User,
    action == Action::"confirmDelivery",
    resource is DeliveryReceipt
)
when {
    principal != resource.shipment.driverOfRecord
}
unless {
    context.fromDepotNetwork
};"}
